package flagship

import (
	"context"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
	"testing"
	"time"

	"github.com/open-feature/go-sdk/openfeature"
)

func TestProviderCacheDisabledByDefault(t *testing.T) {
	var calls atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls.Add(1)
		writeEvaluationResponse(w, true, "on", "TARGETING_MATCH")
	}))
	defer server.Close()

	provider := newTestProvider(t, server.URL, Options{})
	_ = provider.BooleanEvaluation(context.Background(), "k", false, nil)
	_ = provider.BooleanEvaluation(context.Background(), "k", false, nil)

	if calls.Load() != 2 {
		t.Fatalf("calls = %d, want 2", calls.Load())
	}
}

func TestProviderCacheHitServesWithoutRequestAndMarksCached(t *testing.T) {
	var calls atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls.Add(1)
		writeEvaluationResponse(w, true, "on", "TARGETING_MATCH")
	}))
	defer server.Close()

	provider := newTestProvider(t, server.URL, Options{CacheTTL: time.Minute})
	first := provider.BooleanEvaluation(context.Background(), "k", false, nil)
	second := provider.BooleanEvaluation(context.Background(), "k", false, nil)

	if first.Value != true || first.Reason != openfeature.TargetingMatchReason {
		t.Fatalf("first = %#v", first)
	}
	if second.Value != true || second.Reason != openfeature.CachedReason || second.Variant != "on" {
		t.Fatalf("second = %#v", second)
	}
	if calls.Load() != 1 {
		t.Fatalf("calls = %d, want 1", calls.Load())
	}
}

func TestProviderCacheKeyIncludesContext(t *testing.T) {
	var calls atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls.Add(1)
		writeEvaluationResponse(w, true, "on", "TARGETING_MATCH")
	}))
	defer server.Close()

	provider := newTestProvider(t, server.URL, Options{CacheTTL: time.Minute})
	free := openfeature.FlattenedContext{"plan": "free"}
	enterprise := openfeature.FlattenedContext{"plan": "enterprise"}

	_ = provider.BooleanEvaluation(context.Background(), "k", false, free)
	_ = provider.BooleanEvaluation(context.Background(), "k", false, enterprise)
	third := provider.BooleanEvaluation(context.Background(), "k", false, free)

	if third.Reason != openfeature.CachedReason {
		t.Fatalf("third reason = %s, want CACHED", third.Reason)
	}
	if calls.Load() != 2 {
		t.Fatalf("calls = %d, want 2", calls.Load())
	}
}

func TestProviderCacheKeyCanonicalizesNestedObjects(t *testing.T) {
	var calls atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls.Add(1)
		writeEvaluationResponse(w, true, "on", "TARGETING_MATCH")
	}))
	defer server.Close()

	provider := newTestProvider(t, server.URL, Options{CacheTTL: time.Minute})
	first := openfeature.FlattenedContext{"profile": map[string]any{"plan": "enterprise", "region": "us"}}
	second := openfeature.FlattenedContext{"profile": map[string]any{"region": "us", "plan": "enterprise"}}

	_ = provider.BooleanEvaluation(context.Background(), "k", false, first)
	result := provider.BooleanEvaluation(context.Background(), "k", false, second)

	if result.Reason != openfeature.CachedReason || calls.Load() != 1 {
		t.Fatalf("result = %#v, calls = %d", result, calls.Load())
	}
}

func TestProviderCacheKeyIncludesType(t *testing.T) {
	var calls atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls.Add(1)
		writeEvaluationResponse(w, 7, "seven", "DEFAULT")
	}))
	defer server.Close()

	provider := newTestProvider(t, server.URL, Options{CacheTTL: time.Minute})
	_ = provider.IntEvaluation(context.Background(), "k", 0, nil)
	_ = provider.FloatEvaluation(context.Background(), "k", 0, nil)
	third := provider.IntEvaluation(context.Background(), "k", 0, nil)

	if third.Reason != openfeature.CachedReason {
		t.Fatalf("third reason = %s, want CACHED", third.Reason)
	}
	if calls.Load() != 2 {
		t.Fatalf("calls = %d, want 2", calls.Load())
	}
}

func TestProviderCacheExpiresAfterTTL(t *testing.T) {
	var calls atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls.Add(1)
		writeEvaluationResponse(w, true, "on", "DEFAULT")
	}))
	defer server.Close()

	provider := newTestProvider(t, server.URL, Options{CacheTTL: 25 * time.Millisecond})
	_ = provider.BooleanEvaluation(context.Background(), "k", false, nil)
	second := provider.BooleanEvaluation(context.Background(), "k", false, nil)
	time.Sleep(50 * time.Millisecond)
	third := provider.BooleanEvaluation(context.Background(), "k", false, nil)

	if second.Reason != openfeature.CachedReason {
		t.Fatalf("second reason = %s, want CACHED", second.Reason)
	}
	if third.Reason == openfeature.CachedReason {
		t.Fatalf("third reason = %s, want non-cached", third.Reason)
	}
	if calls.Load() != 2 {
		t.Fatalf("calls = %d, want 2", calls.Load())
	}
}

func TestProviderCacheEvictsLeastRecentlyUsed(t *testing.T) {
	var calls atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls.Add(1)
		writeEvaluationResponse(w, true, "on", "DEFAULT")
	}))
	defer server.Close()

	provider := newTestProvider(t, server.URL, Options{CacheTTL: time.Minute, CacheMaxSize: 1})
	_ = provider.BooleanEvaluation(context.Background(), "a", false, nil)
	_ = provider.BooleanEvaluation(context.Background(), "b", false, nil)
	third := provider.BooleanEvaluation(context.Background(), "b", false, nil)
	fourth := provider.BooleanEvaluation(context.Background(), "a", false, nil)

	if third.Reason != openfeature.CachedReason {
		t.Fatalf("third reason = %s, want CACHED", third.Reason)
	}
	if fourth.Reason == openfeature.CachedReason {
		t.Fatalf("fourth reason = %s, want non-cached", fourth.Reason)
	}
	if calls.Load() != 3 {
		t.Fatalf("calls = %d, want 3", calls.Load())
	}
}

func TestProviderCacheDoesNotStoreDisabledResults(t *testing.T) {
	var calls atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls.Add(1)
		writeEvaluationResponse(w, true, "on", "DISABLED")
	}))
	defer server.Close()

	provider := newTestProvider(t, server.URL, Options{CacheTTL: time.Minute})
	first := provider.BooleanEvaluation(context.Background(), "k", false, nil)
	second := provider.BooleanEvaluation(context.Background(), "k", false, nil)

	if first.Reason != openfeature.DisabledReason || second.Reason != openfeature.DisabledReason {
		t.Fatalf("first = %#v second = %#v", first, second)
	}
	if calls.Load() != 2 {
		t.Fatalf("calls = %d, want 2", calls.Load())
	}
}

func TestProviderCacheDoesNotStoreErrors(t *testing.T) {
	var calls atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if calls.Add(1) == 1 {
			http.Error(w, "temporary", http.StatusInternalServerError)
			return
		}
		writeEvaluationResponse(w, true, "on", "DEFAULT")
	}))
	defer server.Close()

	provider := newTestProvider(t, server.URL, Options{CacheTTL: time.Minute})
	first := provider.BooleanEvaluation(context.Background(), "k", false, nil)
	second := provider.BooleanEvaluation(context.Background(), "k", false, nil)

	requireResolutionErrorCode(t, first.ResolutionDetail(), openfeature.GeneralCode)
	if second.Value != true || second.ResolutionDetail().ErrorCode != "" {
		t.Fatalf("second = %#v", second)
	}
	if calls.Load() != 2 {
		t.Fatalf("calls = %d, want 2", calls.Load())
	}
}

func TestProviderCacheDoesNotStoreTypeMismatches(t *testing.T) {
	var calls atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if calls.Add(1) == 1 {
			writeEvaluationResponse(w, "not a bool", "bad", "DEFAULT")
			return
		}
		writeEvaluationResponse(w, true, "on", "DEFAULT")
	}))
	defer server.Close()

	provider := newTestProvider(t, server.URL, Options{CacheTTL: time.Minute})
	first := provider.BooleanEvaluation(context.Background(), "k", false, nil)
	second := provider.BooleanEvaluation(context.Background(), "k", false, nil)

	requireResolutionErrorCode(t, first.ResolutionDetail(), openfeature.TypeMismatchCode)
	if second.Value != true || second.ResolutionDetail().ErrorCode != "" {
		t.Fatalf("second = %#v", second)
	}
	if calls.Load() != 2 {
		t.Fatalf("calls = %d, want 2", calls.Load())
	}
}

func TestProviderShutdownClearsCache(t *testing.T) {
	var calls atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls.Add(1)
		writeEvaluationResponse(w, true, "on", "DEFAULT")
	}))
	defer server.Close()

	provider := newTestProvider(t, server.URL, Options{CacheTTL: time.Minute})
	_ = provider.BooleanEvaluation(context.Background(), "k", false, nil)
	provider.Shutdown()
	second := provider.BooleanEvaluation(context.Background(), "k", false, nil)

	if second.Reason == openfeature.CachedReason {
		t.Fatalf("second reason = %s, want non-cached", second.Reason)
	}
	if calls.Load() != 2 {
		t.Fatalf("calls = %d, want 2", calls.Load())
	}
}

import { describe, it, expect, beforeEach, vi } from 'vitest';
import type { Logger } from '@openfeature/server-sdk';
import { FlagshipServerProvider } from '../src/server-provider.js';
import type { FlagshipBinding, FlagshipBindingEvaluationDetails } from '../src/types.js';

global.fetch = vi.fn();

const noopLogger: Logger = {
	debug: () => {},
	info: () => {},
	warn: () => {},
	error: () => {},
};

function mockResponse(value: unknown, reason = 'TARGETING_MATCH', variant = 'on'): void {
	(global.fetch as any).mockResolvedValueOnce({
		ok: true,
		json: async () => ({ flagKey: 'flag', value, variant, reason }),
	});
}

function createMockBinding(): FlagshipBinding {
	return {
		get: vi.fn((_flagKey: string, defaultValue?: unknown) => Promise.resolve(defaultValue)),
		getBooleanValue: vi.fn((_flagKey: string, defaultValue: boolean) => Promise.resolve(defaultValue)),
		getStringValue: vi.fn((_flagKey: string, defaultValue: string) => Promise.resolve(defaultValue)),
		getNumberValue: vi.fn((_flagKey: string, defaultValue: number) => Promise.resolve(defaultValue)),
		getObjectValue: vi.fn(<T extends object>(_flagKey: string, defaultValue: T) => Promise.resolve(defaultValue)),
		getBooleanDetails: vi.fn((flagKey: string): Promise<FlagshipBindingEvaluationDetails<boolean>> =>
			Promise.resolve({ flagKey, value: true, variant: 'on', reason: 'TARGETING_MATCH' }),
		),
		getStringDetails: vi.fn((flagKey: string, defaultValue: string): Promise<FlagshipBindingEvaluationDetails<string>> =>
			Promise.resolve({ flagKey, value: defaultValue, reason: 'DEFAULT' }),
		),
		getNumberDetails: vi.fn((flagKey: string, defaultValue: number): Promise<FlagshipBindingEvaluationDetails<number>> =>
			Promise.resolve({ flagKey, value: defaultValue, reason: 'DEFAULT' }),
		),
		getObjectDetails: vi.fn(<T extends object>(flagKey: string, defaultValue: T): Promise<FlagshipBindingEvaluationDetails<T>> =>
			Promise.resolve({ flagKey, value: defaultValue, reason: 'DEFAULT' }),
		),
	};
}

describe('FlagshipServerProvider caching', () => {
	beforeEach(() => {
		(global.fetch as any).mockReset();
	});

	it('does not cache when cacheTtl is unset (default)', async () => {
		mockResponse(true);
		mockResponse(true);
		const provider = new FlagshipServerProvider({ endpoint: 'https://api.example.com/evaluate' });

		await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1' }, noopLogger);
		await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1' }, noopLogger);

		expect(global.fetch).toHaveBeenCalledTimes(2);
	});

	it('serves a cache hit without a second fetch and marks it CACHED', async () => {
		mockResponse(true, 'TARGETING_MATCH', 'on');
		const provider = new FlagshipServerProvider({ endpoint: 'https://api.example.com/evaluate', cacheTtl: 60_000 });

		const first = await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1' }, noopLogger);
		const second = await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1' }, noopLogger);

		expect(global.fetch).toHaveBeenCalledTimes(1);
		expect(first.reason).toBe('TARGETING_MATCH');
		expect(second.value).toBe(true);
		expect(second.variant).toBe('on');
		expect(second.reason).toBe('CACHED');
	});

	it('keeps a separate entry per evaluation context', async () => {
		mockResponse(true);
		mockResponse(false);
		const provider = new FlagshipServerProvider({ endpoint: 'https://api.example.com/evaluate', cacheTtl: 60_000 });

		const a = await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1' }, noopLogger);
		const b = await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u2' }, noopLogger);

		expect(global.fetch).toHaveBeenCalledTimes(2);
		expect(a.value).toBe(true);
		expect(b.value).toBe(false);
	});

	it('shares cache entries for equivalent nested objects with different key order', async () => {
		mockResponse(true);
		const provider = new FlagshipServerProvider({ endpoint: 'https://api.example.com/evaluate', cacheTtl: 60_000 });

		await provider.resolveBooleanEvaluation('flag', false, { profile: { plan: 'enterprise', region: 'us' } } as any, noopLogger);
		const cached = await provider.resolveBooleanEvaluation(
			'flag',
			false,
			{ profile: { region: 'us', plan: 'enterprise' } } as any,
			noopLogger,
		);

		expect(global.fetch).toHaveBeenCalledTimes(1);
		expect(cached.reason).toBe('CACHED');
	});

	it('keeps separate cache entries for differently ordered arrays', async () => {
		mockResponse(true);
		mockResponse(false);
		const provider = new FlagshipServerProvider({ endpoint: 'https://api.example.com/evaluate', cacheTtl: 60_000 });

		await provider.resolveBooleanEvaluation('flag', false, { tags: ['beta', 'internal'] } as any, noopLogger);
		await provider.resolveBooleanEvaluation('flag', false, { tags: ['internal', 'beta'] } as any, noopLogger);

		expect(global.fetch).toHaveBeenCalledTimes(2);
	});

	it('keeps separate cache entries for null and absent attributes', async () => {
		mockResponse(true);
		mockResponse(false);
		const provider = new FlagshipServerProvider({ endpoint: 'https://api.example.com/evaluate', cacheTtl: 60_000 });

		await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1', plan: null }, noopLogger);
		await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1' }, noopLogger);

		expect(global.fetch).toHaveBeenCalledTimes(2);
	});

	it('keeps separate cache entries for values of different primitive types', async () => {
		mockResponse(true);
		mockResponse(false);
		const provider = new FlagshipServerProvider({ endpoint: 'https://api.example.com/evaluate', cacheTtl: 60_000 });

		await provider.resolveBooleanEvaluation('flag', false, { age: 30 }, noopLogger);
		await provider.resolveBooleanEvaluation('flag', false, { age: '30' }, noopLogger);

		expect(global.fetch).toHaveBeenCalledTimes(2);
	});

	it('re-fetches after the TTL expires', async () => {
		mockResponse(true);
		mockResponse(true);
		const provider = new FlagshipServerProvider({ endpoint: 'https://api.example.com/evaluate', cacheTtl: 20 });

		await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1' }, noopLogger);
		await new Promise((resolve) => setTimeout(resolve, 40));
		await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1' }, noopLogger);

		expect(global.fetch).toHaveBeenCalledTimes(2);
	});

	it('evicts least-recently-used entries beyond cacheMaxSize', async () => {
		mockResponse(true); // u1
		mockResponse(true); // u2
		mockResponse(true); // u1 again (evicted)
		const provider = new FlagshipServerProvider({
			endpoint: 'https://api.example.com/evaluate',
			cacheTtl: 60_000,
			cacheMaxSize: 1,
		});

		await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1' }, noopLogger);
		await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u2' }, noopLogger);
		await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1' }, noopLogger);

		expect(global.fetch).toHaveBeenCalledTimes(3);
	});

	it('does not cache DISABLED results', async () => {
		mockResponse(true, 'DISABLED');
		mockResponse(true, 'DISABLED');
		const provider = new FlagshipServerProvider({ endpoint: 'https://api.example.com/evaluate', cacheTtl: 60_000 });

		await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1' }, noopLogger);
		await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1' }, noopLogger);

		expect(global.fetch).toHaveBeenCalledTimes(2);
	});

	it('does not cache error results', async () => {
		(global.fetch as any).mockResolvedValue(new Response(null, { status: 404 }));
		const provider = new FlagshipServerProvider({ endpoint: 'https://api.example.com/evaluate', cacheTtl: 60_000 });

		await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1' }, noopLogger);
		await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1' }, noopLogger);

		expect(global.fetch).toHaveBeenCalledTimes(2);
	});

	it('clears the cache on close', async () => {
		mockResponse(true);
		mockResponse(true);
		const provider = new FlagshipServerProvider({ endpoint: 'https://api.example.com/evaluate', cacheTtl: 60_000 });

		await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1' }, noopLogger);
		await provider.onClose();
		await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1' }, noopLogger);

		expect(global.fetch).toHaveBeenCalledTimes(2);
	});

	it('caches binding-mode evaluations', async () => {
		const binding = createMockBinding();
		const provider = new FlagshipServerProvider({ binding, cacheTtl: 60_000 });

		const first = await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1' }, noopLogger);
		const second = await provider.resolveBooleanEvaluation('flag', false, { targetingKey: 'u1' }, noopLogger);

		expect(binding.getBooleanDetails).toHaveBeenCalledTimes(1);
		expect(first.reason).toBe('TARGETING_MATCH');
		expect(second.value).toBe(true);
		expect(second.reason).toBe('CACHED');
	});
});

