            (json!(1), true, true),
            (json!("x"), true, true),
            (json!([]), false, false),
            (json!({}), false, false),
        ];

        for (value, scalar, primitive) in cases {
            assert_eq!(is_scalar(&value), scalar, "scalar: {value}");
            assert_eq!(is_primitive(&value), primitive, "primitive: {value}");
        }
    }

