            "1900-02-29T00:00:00Z",
            "2023-01-01T24:00:00Z",
            "2023-01-01T00:00:00+25:00",
            "2023-01-01T00:00:00-25:00",
            "2023-01-01T00:00:00+24:61",
            "2023-01-01T00:00:00+00:61",
        ];

        for value in cases {
            assert_eq!(parse_iso_millis(value), None, "value: {value}");
        }
    }

    #[test]
    fn compares_numeric_and_iso_values() {
        let cases = [
            (json!(2), json!("10"), Some(Ordering::Less)),
            (json!(true), json!(1), Some(Ordering::Equal)),
            (json!("Infinity"), json!(10), Some(Ordering::Greater)),
            (json!("-Infinity"), json!(-10), Some(Ordering::Less)),
            (json!("-0"), json!(0), Some(Ordering::Equal)),
            (
                json!("2023-01-01T00:00:00.123999Z"),
                json!("2023-01-01T00:00:00.123Z"),
                Some(Ordering::Equal),
            ),
            (
                json!("2023-01-01T1:02:03Z"),
                json!("2023-01-01T01:02:03Z"),
                Some(Ordering::Equal),
            ),
            (
                json!("2023-01-01T01:02:03,1239+24:60"),
                json!("2023-01-01T01:02:03.123+24:60"),
                Some(Ordering::Equal),
            ),
            (
                json!("2023-02-30T00:00:00Z"),
                json!("2023-03-01T00:00:00Z"),
                None,
            ),
            (json!("10"), json!("2023-01-01T00:00:00Z"), None),
            (json!("not-a-number"), json!(1), None),
            (json!(null), json!(1), None),
        ];

        for (actual, expected, ordering) in cases {
            assert_eq!(compare_values(&actual, &expected), ordering);
        }
    }

    #[test]
    fn caches_repeated_actual_numeric_and_date_coercions() {
        let numeric = Value::String(format!("0x{}", "f".repeat(2_048)));
        let numeric_target = json!(0);
        let date = Value::String(format!("1970-01-01T00:00:00.{}Z", "1".repeat(2_048)));
        let date_target = json!("1970-01-01T00:00:00Z");
        let mut cache = CoercionCache::default();

        for _ in 0..100 {
            assert_eq!(
                cache.compare_values(&numeric, &numeric_target),
                Some(Ordering::Greater)
            );
            assert_eq!(
                cache.compare_values(&date, &date_target),
                Some(Ordering::Greater)
            );
        }

        assert_eq!(cache.numbers.len(), 1);
        assert_eq!(cache.dates.len(), 1);
    }

    #[test]
    fn maps_out_of_range_arbitrary_precision_json_numbers_to_infinity() {
        let positive = serde_json::from_str::<Value>("1e400");
        let negative = serde_json::from_str::<Value>("-1e400");
        if positive.is_err() || negative.is_err() {
            // Only reachable with serde_json's arbitrary_precision feature.
            assert!(positive.is_err());
            assert!(negative.is_err());
            return;
        }

        let positive = positive.unwrap_or(Value::Null);
        let negative = negative.unwrap_or(Value::Null);
        assert_eq!(js_string(&positive), "Infinity");
        assert_eq!(js_string(&negative), "-Infinity");
        assert_eq!(js_number(&positive), f64::INFINITY);
        assert_eq!(js_number(&negative), f64::NEG_INFINITY);
    }

    #[test]
    fn applies_collection_membership_stringification_rules() {
        let values = json!(["US", 1, true, null, ["a", "b"], {"x": 1}]);
        let values = values.as_array().unwrap_or_else(|| unreachable!());

        assert!(contains_value(values, &json!("1")));
        assert!(contains_value(values, &json!("a,b")));
        assert!(contains_value(values, &json!("[object Object]")));
        assert!(!contains_value(values, &Value::Null));
        assert!(contains_primitive_value(values, &json!("true")));
        assert!(!contains_primitive_value(values, &json!("a,b")));
    }
}

# @cloudflare/flagship

[![npm version](https://img.shields.io/npm/v/@cloudflare/flagship.svg)](https://www.npmjs.com/package/@cloudflare/flagship)
[![npm downloads](https://img.shields.io/npm/dm/@cloudflare/flagship.svg)](https://www.npmjs.com/package/@cloudflare/flagship)
[![license](https://img.shields.io/npm/l/@cloudflare/flagship.svg)](https://github.com/cloudflare/flagship/blob/main/LICENSE)

[OpenFeature](https://openfeature.dev)-compliant provider SDK for [Flagship](https://github.com/cloudflare/flagship), Cloudflare's globally distributed, low-latency feature flag platform.

Server-side (Node.js, Cloudflare Workers) and client-side (browser) support via isolated sub-path exports. Tree-shakeable — importing `@cloudflare/flagship/server` never loads `@openfeature/web-sdk` and vice versa.

## Install

**Server-side** (Node.js, Cloudflare Workers):

```bash
npm install @cloudflare/flagship @openfeature/server-sdk
```

**Client-side** (browser):

```bash
npm install @cloudflare/flagship @openfeature/web-sdk
```

## Quick start — server

```typescript
import { OpenFeature } from '@openfeature/server-sdk';
import { FlagshipServerProvider } from '@cloudflare/flagship/server';

await OpenFeature.setProviderAndWait(
  new FlagshipServerProvider({ appId: 'your-app-id', accountId: 'your-account-id', authToken: 'your-token' }),
);

const client = OpenFeature.getClient();
const enabled = await client.getBooleanValue('dark-mode', false, { userId: 'user-123' });
```

## Quick start — Cloudflare Workers

The recommended approach for Cloudflare Workers. Uses a wrangler binding — no HTTP overhead, no auth tokens needed.

Configure in `wrangler.json`:

```jsonc
{
  "flagship": [{ "binding": "FLAGS", "app_id": "<your-app-id>" }]
}
```

```typescript
import { OpenFeature } from '@openfeature/server-sdk';
import { FlagshipServerProvider } from '@cloudflare/flagship/server';
import type { FlagshipBinding } from '@cloudflare/flagship/server';

export default {
  async fetch(request: Request, env: { FLAGS: FlagshipBinding }): Promise<Response> {
    await OpenFeature.setProviderAndWait(new FlagshipServerProvider({ binding: env.FLAGS }));

    const client = OpenFeature.getClient();
    const darkMode = await client.getBooleanValue('dark-mode', false, {
      targetingKey: new URL(request.url).searchParams.get('userId') ?? 'anonymous',
    });

    return Response.json({ darkMode });
  },
};
```

## Quick start — HTTP

For Workers without a Flagship binding, or non-Workers server environments:

```typescript
import { OpenFeature } from '@openfeature/server-sdk';
import { FlagshipServerProvider } from '@cloudflare/flagship/server';

let initialized = false;

export default {
  async fetch(request: Request): Promise<Response> {
    if (!initialized) {
      await OpenFeature.setProviderAndWait(
        new FlagshipServerProvider({ appId: 'your-app-id', accountId: 'your-account-id', authToken: 'your-token' }),
      );
      initialized = true;
    }

    const client = OpenFeature.getClient();
    const darkMode = await client.getBooleanValue('dark-mode', false, {
      userId: new URL(request.url).searchParams.get('userId') ?? 'anonymous',
    });

    return Response.json({ darkMode });
  },
};
```

## Structured evaluation context

Binding and HTTP modes support nested objects, arrays, and `null` in evaluation context. Dates are recursively converted to ISO-8601 strings.

```typescript
const checkout = await client.getStringValue('checkout-flow', 'control', {
  targetingKey: 'user-123',
  profile: { account: { plan: 'enterprise' } },
  tags: ['beta', 'internal'],
});
```

Primitive-only HTTP context keeps using GET query parameters. Structured context, including `null`, uses the JSON POST endpoint; in browsers this adds a CORS preflight request. Only strings, numbers, booleans, `null`, dates, arrays, and plain objects are supported. Anything else, including cyclic values, resolves with `INVALID_CONTEXT` without making a binding or HTTP call.

## Caching

The server provider can cache evaluations to avoid a network round-trip (HTTP mode) or binding call (binding mode) for repeated flag/context pairs. Caching is **off by default** and enabled by setting `cacheTtl`:

```typescript
new FlagshipServerProvider({
  appId: 'your-app-id',
  accountId: 'your-account-id',
  cacheTtl: 30_000, // ms — enables caching; values may be up to this stale
  cacheMaxSize: 1000, // max cached entries, LRU-evicted (default: 1000)
});
```

Each entry is keyed by flag key, type, and the **full evaluation context**, so distinct contexts never share a value. Cache hits resolve with `reason: 'CACHED'`. Disabled flags and errors are never cached. Because freshness is TTL-based, a flag change in Flagship takes effect after the entry expires.

## Local evaluation

Server providers can download flag definitions once and evaluate flags in-process with no network call per evaluation. Definitions refresh lazily in the background (stale-while-revalidate on evaluate).

```typescript
await OpenFeature.setProviderAndWait(
  new FlagshipServerProvider({
    appId: 'your-app-id',
    accountId: 'your-account-id', // required — used as the rollout hash seed
    authToken: '[REDACTED]', // needs app **read** permission, not evaluate
    localEvaluation: true,
    refreshInterval: 30_000, // ms between background refreshes (default 30s)
  }),
);
```

Notes:

- Incompatible with `binding` mode and with `cacheTtl` (there is nothing to cache).
- `accountId` is always required in local mode, including when `endpoint` is used.
- With `endpoint`, the URL path must end in `/evaluate` so `/definitions` can be derived.
- Local evaluations do **not** appear in server-side analytics.
- See [`examples/server-local.ts`](./examples/server-local.ts).

## Quick start — browser

```typescript
import { OpenFeature } from '@openfeature/web-sdk';
import { FlagshipClientProvider } from '@cloudflare/flagship/web';

await OpenFeature.setProviderAndWait(
  new FlagshipClientProvider({
    appId: 'your-app-id',
    accountId: 'your-account-id',
    authToken: 'your-token',
  }),
);

await OpenFeature.setContext({ userId: 'user-123', plan: 'premium' });

const client = OpenFeature.getClient();
const darkMode = client.getBooleanValue('dark-mode', false);
```

## Features

| Feature               | Description                                                                    |
| --------------------- | ------------------------------------------------------------------------------ |
| OpenFeature compliant | Implements the CNCF OpenFeature specification                                  |
| Workers binding       | Native wrangler binding support — zero HTTP overhead, no auth tokens           |
| Server + client       | Async per-request (server) and sync cache-based (browser) providers            |
| Server providers      | `FlagshipServerProvider` works via HTTP, local evaluation, or wrangler binding |
| Local evaluation      | In-process evaluation from downloaded definitions (`localEvaluation: true`)    |
| All flag types        | Boolean, string, number, and object (JSON)                                     |
| Authentication        | `authToken` option adds `Authorization: Bearer` to every request (HTTP only)   |
| Logging               | `logging` option surfaces fetch errors and cache misses (off by default)       |
| Response caching      | Opt-in per-context TTL + LRU cache via `cacheTtl` (off by default)             |
| Retries + timeouts    | Configurable retry logic with `AbortController`-based timeouts (HTTP only)     |
| Custom transport      | Inject `fetch` per client or per call — no global mutation (HTTP only)         |
| Cancellation          | Caller `AbortSignal` aborts the in-flight request, never retried (HTTP only)   |
| Hooks                 | Built-in `LoggingHook` and `TelemetryHook`                                     |
| Tree-shakeable        | Server and client bundles are fully isolated                                   |
| TypeScript            | Strict types throughout                                                        |

## Packages

| Export                        | Description                      | Peer dependency           |
| ----------------------------- | -------------------------------- | ------------------------- |
| `@cloudflare/flagship`        | Core client, types, errors       | None                      |
| `@cloudflare/flagship/server` | `FlagshipServerProvider` + hooks | `@openfeature/server-sdk` |
| `@cloudflare/flagship/web`    | `FlagshipClientProvider`         | `@openfeature/web-sdk`    |

## Documentation

- [API reference](./API.md)
- [OpenFeature specification](https://openfeature.dev/specification/)
- [Examples](./examples/)

## Development

```bash
pnpm install         # install dependencies
pnpm run dev         # watch mode
pnpm run test        # run tests
pnpm run build       # build for distribution
```

## Contributing

Contributions are welcome. Please open an issue first to discuss what you'd like to change. See the [repository](https://github.com/cloudflare/flagship) for more details.

