func valuesEqual(got, want any) bool {
	// json.Number vs float/int from expected comparison.
	switch g := got.(type) {
	case json.Number:
		switch w := want.(type) {
		case json.Number:
			gf, gerr := g.Float64()
			wf, werr := w.Float64()
			if gerr == nil && werr == nil {
				return gf == wf
			}
			return g.String() == w.String()
		case float64:
			gf, err := g.Float64()
			return err == nil && gf == w
		case int:
			gi, err := g.Int64()
			return err == nil && gi == int64(w)
		case int64:
			gi, err := g.Int64()
			return err == nil && gi == w
		}
	}
	return reflect.DeepEqual(got, want)
}

